{
  "findings": [
    {
      "check_id": "CKV_GCP_32",
      "title": "Ensure 'Block Project-wide SSH keys' is enabled for VM instances",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Project-wide SSH keys are enabled by default, which can allow unintended access to the instance. Disabling them ensures only explicitly defined SSH keys are used."
    },
    {
      "check_id": "CKV_GCP_38",
      "title": "Ensure VM disks for critical VMs are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The boot disk is not configured to use Customer Supplied Encryption Keys (CSEK), which provides stronger control over encryption keys."
    },
    {
      "check_id": "CKV_GCP_30",
      "title": "Ensure that instances are not configured to use the default service account",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Using the default service account can lead to over-privileged access. A custom service account with least privilege should be used."
    },
    {
      "check_id": "CKV_GCP_31",
      "title": "Ensure that instances are not configured to use the default service account with full access to all Cloud APIs",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The default service account is configured with the 'cloud-platform' scope, granting full access to all Cloud APIs, which violates the principle of least privilege."
    },
    {
      "check_id": "CKV_GCP_40",
      "title": "Ensure that Compute instances do not have public IP addresses",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "The instance has a public IP address configured via 'access_config', which increases the risk of unauthorized access."
    },
    {
      "check_id": "CKV_GCP_35",
      "title": "Ensure 'Enable connecting to serial ports' is not enabled for VM Instance",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Serial port access is enabled, which can expose the instance to unauthorized access or debugging attempts."
    },
    {
      "check_id": "CKV_GCP_39",
      "title": "Ensure Compute instances are launched with Shielded VM enabled",
      "resource": "google_compute_instance.backup_orchestration_engine",
      "severity": "MEDIUM",
      "explanation": "Shielded VM is not enabled, which provides additional security features such as secure boot and integrity monitoring."
    }
  ],
  "patched_code": "resource \"google_compute_instance\" \"backup_orchestration_engine\" {\n  name         = \"enterprise-disaster-recovery-orchestration-platform-compute-orchestration\"\n  machine_type = \"e2-medium\"\n  zone         = \"${var.primary_region}-a\"\n  boot_disk {\n    initialize_params {\n      image = \"debian-cloud/debian-11\"\n      size  = 50\n    }\n    encryption_key {\n      kms_key_self_link = var.kms_key_self_link\n    }\n  }\n  network_interface {\n    network    = google_compute_network.dr_vpc.id\n    subnetwork = google_compute_subnetwork.management_subnet.id\n  }\n  service_account {\n    email  = var.custom_service_account_email\n    scopes = [\"https://www.googleapis.com/auth/compute.readonly\"]\n  }\n  metadata = {\n    block-project-ssh-keys = true\n    serial-port-enable     = false\n    startup-script         = file(\"${path.module}/scripts/orchestration-startup.sh\")\n  }\n  tags = [\"dr-internal\", \"orchestration-engine\"]\n  shielded_instance_config {\n    enable_secure_boot          = true\n    enable_vtpm                 = true\n    enable_integrity_monitoring = true\n  }\n  depends_on = [\n    google_storage_bucket.primary_backup_storage,\n    google_sql_database_instance.recovery_database\n  ]\n}",
  "fix_summary": "Disabled project-wide SSH keys, removed public IP configuration, disabled serial port access, enabled Shielded VM, replaced the default service account with a custom one, restricted API scopes, and added Customer Supplied Encryption Keys (CSEK) for the boot disk."
}
